void ChromeContentBrowserClient::CreateWebSocket(
    content::RenderFrameHost* frame,
    WebSocketFactory factory,
    const GURL& url,
    const net::SiteForCookies& site_for_cookies,
    const std::optional<std::string>& user_agent,
    mojo::PendingRemote<network::mojom::WebSocketHandshakeClient>
        handshake_client,
    content::ContentBrowserClient::WebSocketOptions options) {
#if BUILDFLAG(ENABLE_EXTENSIONS_CORE)
  // TODO(crbug.com/40195467): Request w/o a frame also should be proxied.
  if (!frame) {
    return;
  }
  auto* web_request_api =
      extensions::BrowserContextKeyedAPIFactory<extensions::WebRequestAPI>::Get(
          frame->GetBrowserContext());

  DCHECK(web_request_api);
  web_request_api->ProxyWebSocket(
      frame, std::move(factory), url, site_for_cookies, user_agent,
      std::move(handshake_client), std::move(options.header_client));
#endif
}

void ChromeContentBrowserClient::WillCreateWebTransport(
    int process_id,
    int frame_routing_id,
    const GURL& url,
    const url::Origin& initiator_origin,
    mojo::PendingRemote<network::mojom::WebTransportHandshakeClient>
        handshake_client,
    WillCreateWebTransportCallback callback) {
#if BUILDFLAG(ENABLE_EXTENSIONS_CORE)
  DCHECK_CURRENTLY_ON(BrowserThread::UI);
  // TODO(crbug.com/40195467): Add a unit test which calls
  // ChromeContentBrowserClient::WillCreateWebTransport() with invalid process
  // id and routing id.
  auto* render_process_host = content::RenderProcessHost::FromID(process_id);
  if (!render_process_host) {
    std::move(callback).Run(std::move(handshake_client), std::nullopt);
    return;
  }
  content::BrowserContext* browser_context =
      render_process_host->GetBrowserContext();
  auto* web_request_api =
      extensions::BrowserContextKeyedAPIFactory<extensions::WebRequestAPI>::Get(
          browser_context);
  // NOTE: Some unit test environments do not initialize BrowserContextKeyedAPI
  // factories like WebRequestAPI.
  if (!web_request_api) {
    std::move(callback).Run(std::move(handshake_client), std::nullopt);
    return;
  }
  web_request_api->ProxyWebTransport(
      *render_process_host, frame_routing_id, url, initiator_origin,
      std::move(handshake_client), std::move(callback));
#else
  std::move(callback).Run(std::move(handshake_client), std::nullopt);
#endif
}

bool ChromeContentBrowserClient::WillCreateRestrictedCookieManager(
    network::mojom::RestrictedCookieManagerRole role,
    content::BrowserContext* browser_context,
    const url::Origin& origin,
    const net::IsolationInfo& isolation_info,
    bool is_service_worker,
    int process_id,
    int routing_id,
    bool prefer_bound_cookie_context,

  // (where `frame_routing_id` is not kRoutingIdNone), it is scoped to a
  // specific creator document. If that document is no longer valid (e.g., due
  // to a navigation committing a new document in the same frame, or frame
  // destruction), abort the connection. For Shared and Service Workers
  // (`frame_routing_id` is kRoutingIdNone), they operate independently of any
  // document lifecycle, so we skip this check.
  if (frame_id_.frame_routing_id != IPC::mojom::kRoutingIdNone &&
      !weak_document_.AsRenderFrameHostIfValid()) {
    return;
  }

  if (auto error = network::VerifyWebSocketConnectParameters(
          url, requested_protocols, isolation_info_)) {
    mojo::ReportBadMessage(*error);
    return;
  }

  RenderProcessHost* process = RenderProcessHost::FromID(frame_id_.child_id);
  if (!process) {
    return;
  }

  RenderFrameHost* frame = RenderFrameHost::FromID(frame_id_);
  net::handles::NetworkHandle target_network =
      net::handles::kInvalidNetworkHandle;
  if (frame) {
    if (auto* web_contents = WebContents::FromRenderFrameHost(frame)) {
      target_network = web_contents->GetTargetNetwork();
    }
  }

  content::ContentBrowserClient::WebSocketOptions options =
      GetContentClient()->browser()->GetWebSocketOptions(frame);

  content::ContentBrowserClient::WebSocketFactory factory = base::BindOnce(
      ConnectCalledByContentBrowserClient, requested_protocols,
      storage_access_api_status_, isolation_info_, frame_id_,
      devtools_worker_token_, origin_, client_security_state_->Clone(),
      options.options, std::move(throttling_profile_id),
      network_restrictions_id_, target_address_space, target_network);

  if (GetContentClient()->browser()->WillInterceptWebSocket(frame)) {
    GetContentClient()->browser()->CreateWebSocket(
        frame, std::move(factory), url, isolation_info_.site_for_cookies(),
        user_agent, std::move(handshake_client), std::move(options));
    return;
  }

  net::HttpRequestHeaders headers;
  if (user_agent) {
    headers.SetHeader(net::HttpRequestHeaders::kUserAgent, *user_agent);
  }
  devtools_instrumentation::ApplyExtraHeadersForWebSocket(
      frame_id_, devtools_worker_token_, &headers);

  std::vector<network::mojom::HttpHeaderPtr> additional_headers;
  for (net::HttpRequestHeaders::Iterator it(headers); it.GetNext();) {
    additional_headers.push_back(
        network::mojom::HttpHeader::New(it.name(), it.value()));
  }

  std::move(factory).Run(url, std::move(additional_headers),
                         std::move(handshake_client), mojo::NullRemote(),
                         std::move(options.header_client));
}

void WebSocketConnectorImpl::ConnectCalledByContentBrowserClient(
    const std::vector<std::string>& requested_protocols,

          frame_, url, std::move(handshake_client), std::move(tracker)),
      std::move(client_receiver));

  mojo::PendingRemote<network::mojom::URLLoaderNetworkServiceObserver>
      url_loader_network_observer;
  // URLLoaderNetworkObserver created based on the context that is creating the
  // WebTransport connection. If no `frame_` is present, this indicates that the
  // WebTransport connection was created from a service worker or shared worker.
  if (frame_) {
    url_loader_network_observer = frame_->CreateURLLoaderNetworkObserver();
  } else {
    content::StoragePartition* storage_partition =
        process->GetStoragePartition();
    // TODO(crbug.com/379869738): Remove FromUnsafeValue.
    url_loader_network_observer =
        static_cast<StoragePartitionImpl*>(storage_partition)
            ->CreateURLLoaderNetworkObserverForServiceOrSharedWorker(
                ToOriginatingProcessId(
                    ChildProcessId::FromUnsafeValue(process_id_)),
                origin_);
  }

  GetContentClient()->browser()->WillCreateWebTransport(
      process_id_, frame_ ? frame_->GetRoutingID() : IPC::mojom::kRoutingIdNone,
      url, origin_, std::move(handshake_client_to_pass),
      base::BindOnce(
          &WebTransportConnectorImpl::OnWillCreateWebTransportCompleted,
          weak_factory_.GetWeakPtr(), url, std::move(fingerprints),
          application_protocols, congestion_control,
          anticipated_concurrent_incoming_unidirectional_streams,
          anticipated_concurrent_incoming_bidirectional_streams,
          std::move(additional_headers), std::move(url_loader_network_observer),
